(()=>{'use strict';const buttons=[...document.querySelectorAll('[data-view]')],panels=[...document.querySelectorAll('[data-panel]')];buttons.forEach(button=>button.addEventListener('click',()=>{buttons.forEach(b=>b.setAttribute('aria-selected',String(b===button)));panels.forEach(p=>p.hidden=p.dataset.panel!==button.dataset.view);}));const entries=[['Fashion design','Collections, styling and garment services'],['Hair salon','Hair and beauty appointments'],['School','Education and learner services'],['Tuck shop','Local essentials and products'],['Brand agency','Identity and creative services']];const search=document.getElementById('search'),results=document.getElementById('results');function render(){results.replaceChildren();const q=search.value.trim().toLowerCase();for(const [name,desc] of entries.filter(e=>(e.join(' ')).toLowerCase().includes(q))){const card=document.createElement('div');card.className='card';const strong=document.createElement('strong');strong.textContent=name;const p=document.createElement('p');p.textContent=desc;card.append(strong,p);results.append(card);}if(!results.childElementCount)results.textContent='No demo category matches.';}search.addEventListener('input',render);render();})();